#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>

using namespace std;

struct Point {
    int x, y;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<Point> mackerels;
    vector<Point> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Find initial rectangle for mackerels
    int min_x_m = numeric_limits<int>::max();
    int max_x_m = numeric_limits<int>::min();
    int min_y_m = numeric_limits<int>::max();
    int max_y_m = numeric_limits<int>::min();

    for (const auto& p : mackerels) {
        min_x_m = min(min_x_m, p.x);
        max_x_m = max(max_x_m, p.x);
        min_y_m = min(min_y_m, p.y);
        max_y_m = max(max_y_m, p.y);
    }

    // Count sardines in initial rect
    int count_sardines_in_initial = 0;
    for (const auto& s : sardines) {
        if (s.x >= min_x_m && s.x <= max_x_m && s.y >= min_y_m && s.y <= max_y_m) {
            count_sardines_in_initial++;
        }
    }

    if (count_sardines_in_initial == 0) {
        // Output initial rectangle
        cout << 4 << endl;
        cout << min_x_m << ' ' << min_y_m << endl;
        cout << max_x_m << ' ' << min_y_m << endl;
        cout << max_x_m << ' ' << max_y_m << endl;
        cout << min_x_m << ' ' << max_y_m << endl;
        return 0;
    }

    // Now, we need to find the best candidate
    int best_value = N - count_sardines_in_initial;
    int best_x_left = min_x_m;
    int best_x_right = max_x_m;
    int best_y_bottom = min_y_m;
    int best_y_top = max_y_m;

    for (const auto& s : sardines) {
        // Check if s is inside initial rect
        if (s.x >= min_x_m && s.x <= max_x_m && s.y >= min_y_m && s.y <= max_y_m) {
            // Generate candidates
            int xs = s.x;
            int ys = s.y;

            // Candidate 1: exclude via x_left (new x_right = xs - 1)
            int new_x_right = xs - 1;
            if (new_x_right >= min_x_m) {
                int new_x_left = min_x_m;
                int new_y_bottom = min_y_m;
                int new_y_top = max_y_m;
                // Compute a_candidate and b_candidate
                int a = 0;
                int b = 0;
                for (const auto& p : mackerels) {
                    if (p.x >= new_x_left && p.x <= new_x_right && p.y >= new_y_bottom && p.y <= new_y_top) {
                        a++;
                    }
                }
                for (const auto& s2 : sardines) {
                    if (s2.x >= new_x_left && s2.x <= new_x_right && s2.y >= new_y_bottom && s2.y <= new_y_top) {
                        b++;
                    }
                }
                int current_value = a - b;
                if (current_value > best_value) {
                    best_value = current_value;
                    best_x_left = new_x_left;
                    best_x_right = new_x_right;
                    best_y_bottom = new_y_bottom;
                    best_y_top = new_y_top;
                }
            }

            // Candidate 2: exclude via x_right (new x_left = xs + 1)
            int new_x_left = xs + 1;
            if (new_x_left <= max_x_m) {
                int new_x_right = max_x_m;
                int new_y_bottom = min_y_m;
