                        b++;
                    }
                }
                int current_value = a - b;
                if (current_value > best_value) {
                    best_value = current_value;
                    best_x_left = new_x_left;
                    best_x_right = new_x_right;
                    best_y_bottom = new_y_bottom;
                    best_y_top = new_y_top;
                }
            }

            // Candidate 4: exclude via y_top (new y_bottom = ys + 1)
            int new_y_bottom = ys + 1;
            if (new_y_bottom <= max_y_m) {
                int new_y_top = max_y_m;
                int new_x_left = min_x_m;
