using namespace std;

int main() {
    int N;
    cin >> N;

    vector<pair<int, int>> mackerels;
    vector<pair<int, int>> sardines;

    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Compute initial rectangle for mackerels
    int x_min = mackerels[0].first;
    int x_max = mackerels[0].first;
    int y_min = mackerels[0].second;
    int y_max = mackerels[0].second;

    for (auto& p : mackerels) {
        if (p.first < x_min) x_min = p.first;
        if (p.first > x_max) x_max = p.first;
        if (p.second < y_min) y_min = p.second;
        if (p.second > y_max) y_max = p.second;
    }

    // Adjust for zero width or height
    if (x_max == x_min) {
        x_min = max(0, x_min - 1);
        x_max = min(100000, x_max + 1);
    }
    if (y_max == y_min) {
        y_min = max(0, y_min - 1);
        y_max = min(100000, y_max + 1);
    }

    int best_a = 0;
    int best_b = 0;
    int best_score = 0;
    int best_x1 = x_min;
    int best_x2 = x_max;
    int best_y1 = y_min;
    int best_y2 = y_max;

    // Check initial rectangle
    int a_initial = 0;
    for (auto& p : mackerels) {
        if (p.first >= best_x1 && p.first <= best_x2 && p.second >= best_y1 && p.second <= best_y2) {
            a_initial++;
        }
    }
