    for (auto& s : sardines) {
        if (s.first >= best_x1 && s.first <= best_x2 && s.second >= best_y1 && s.second <= best_y2) {
            b_initial++;
        }
    }
    int score_initial = a_initial - b_initial;
    if (score_initial > best_score) {
        best_score = score_initial;
        best_a = a_initial;
        best_b = b_initial;
        best_x1 = x_min;
        best_x2 = x_max;
        best_y1 = y_min;
        best_y2 = y_max;
    }

    // Now, process each sardine in initial rectangle
    for (auto& s : sardines) {
        if (s.first >= best_x1 && s.first <= best_x2 && s.second >= best_y1 && s.second <= best_y2) {
            // Generate candidates for x and y

            // Candidate 1: reduce x_max to s.x -1
            int x1_candidate = best_x1;
            int x2_candidate = s.first - 1;
            if (x2_candidate >= x1_candidate) {
                int a = 0;
                int b = 0;
                for (auto& p : mackerels) {
                    if (p.first >= x1_candidate && p.first <= x2_candidate && p.second >= best_y1 && p.second <= best_y2) {
                        a++;
                    }
                }
                for (auto& s2 : sardines) {
                    if (s2.first >= x1_candidate && s2.first <= x2_candidate && s2.second >= best_y1 && s2.second <= best_y2) {
                        b++;
                    }
                }
                int score = a - b;
                if (score > best_score) {
                    best_score = score;
                    best_a = a;
                    best_b = b;
                    best_x1 = x1_candidate;
                    best_x2 = x2_candidate;
                    best_y1 = best_y1;
                    best_y2 = best_y2;
                }
            }

            // Candidate 2: increase x_min to s.x +1
            x1_candidate = s.first + 1;
            x2_candidate = best_x2;
            if (x1_candidate <= x2_candidate) {
                int a = 0;
                int b = 0;
                for (auto& p : mackerels) {
                    if (p.first >= x1_candidate && p.first <= x2_candidate && p.second >= best_y1 && p.second <= best_y2) {
                        a++;
                    }
                }
                for (auto& s2 : sardines) {
                    if (s2.first >= x1_candidate && s2.first <= x2_candidate && s2.second >= best_y1 && s2.second <= best_y2) {
                        b++;
                    }
                }
                int score = a - b;
                if (score > best_score) {
                    best_score = score;
                    best_a = a;
                    best_b = b;
                    best_x1 = x1_candidate;
                    best_x2 = x2_candidate;
                    best_y1 = best_y1;
                    best_y2 = best_y2;
                }
            }

            // Candidate 3: reduce y_max to s.y -1
            int y1_candidate = best_y1;
            int y2_candidate = s.second - 1;
            if (y2_candidate >= y1_candidate) {
                int a = 0;
                int b = 0;
                for (auto& p : mackerels) {
                    if (p.first >= best_x1 && p.first <= best_x2 && p.second >= y1_candidate && p.second <= y2_candidate) {
