                    }
                }
                for (auto& s2 : sardines) {
                    if (s2.first >= best_x1 && s2.first <= best_x2 && s2.second >= y1_candidate && s2.second <= y2_candidate) {
                        b++;
                    }
                }
                int score = a - b;
                if (score > best_score) {
                    best_score = score;
                    best_a = a;
                    best_b = b;
                    best_x1 = best_x1;
                    best_x2 = best_x2;
                    best_y1 = y1_candidate;
                    best_y2 = y2_candidate;
                }
            }

            // Candidate 4: increase y_min to s.y +1
            y1_candidate = s.second + 1;
            y2_candidate = best_y2;
            if (y1_candidate <= y2_candidate) {
                int a = 0;
                int b = 0;
                for (auto& p : mackerels) {
