        max_x_m = max(max_x_m, m.first);
        min_y_m = min(min_y_m, m.second);
        max_y_m = max(max_y_m, m.second);
    }

    // Count initial_b
    int initial_b = 0;
    for (auto& s : sardines) {
        if (s.first >= min_x_m && s.first <= max_x_m &&
            s.second >= min_y_m && s.second <= max_y_m) {
            ++initial_b;
        }
    }

    int max_diff = N - initial_b;
    int best_min_x = min_x_m, best_min_y = min_y_m, best_max_x = max_x_m, best_max_y = max_y_m;

    // Function to count mackerels in rectangle
    auto count_mackerels = [&](int min_x, int min_y, int max_x, int max_y) {
        int cnt = 0;
        for (auto& m : mackerels) {
            if (m.first >= min_x && m.first <= max_x && m.second >= min_y && m.second <= max_y) {
                cnt++;
            }
        }
        return cnt;
    };

    // Function to count sardines in rectangle
    auto count_sardines = [&](int min_x, int min_y, int max_x, int max_y) {
        int cnt = 0;
        for (auto& s : sardines) {
            if (s.first >= min_x && s.first <= max_x && s.second >= min_y && s.second <= max_y) {
                cnt++;
            }
        }
        return cnt;
