                    best_min_x = min_x_m;
                    best_min_y = y1;
                    best_max_x = max_x_m;
                    best_max_y = y2;
                }
            }
            // Split on x: left of s.x
            int x1 = min_x_m;
            int x2 = s.first - 1;
            if (x2 >= x1) {
                int a_new = count_mackerels(x1, min_y_m, x2, max_y_m);
                int b_new = count_sardines(x1, min_y_m, x2, max_y_m);
