    int min_x_m = INT_MAX, max_x_m = INT_MIN;
    int min_y_m = INT_MAX, max_y_m = INT_MIN;
    for (const auto &p : mackerels) {
        min_x_m = min(min_x_m, p.x);
        max_x_m = max(max_x_m, p.x);
        min_y_m = min(min_y_m, p.y);
        max_y_m = max(max_y_m, p.y);
    }

    // Function to count number of points in a rectangle
    auto count_points = [&](const vector<Point> &points, int x1, int y1, int x2, int y2) -> int {
        int cnt = 0;
        for (const auto &p : points) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                ++cnt;
            }
        }
        return cnt;
    };

    // Initial rectangle
    int a_initial = N;
    int b_initial = count_points(sardines, min_x_m, min_y_m, max_x_m, max_y_m);
    int best_score = a_initial - b_initial;
    int best_min_x = min_x_m, best_max_x = max_x_m;
    int best_min_y = min_y_m, best_max_y = max_y_m;

    // For each sardine, check if inside initial rectangle
    for (const auto &s : sardines) {
        int sx = s.x, sy = s.y;
        if (sx < min_x_m || sx > max_x_m || sy < min_y_m || sy > max_y_m) {
            continue;
        }

        // Generate four adjusted rectangles
        // 1. reduce max_x to sx - 1
        int x1 = min_x_m, x2 = sx - 1;
