                best_min_y = y1;
                best_max_y = y2;
            }
        }

        // 2. increase min_x to sx + 1
        x1 = sx + 1;
        x2 = max_x_m;
        y1 = min_y_m;
        y2 = max_y_m;
        if (x1 <= x2 && y1 <= y2) {
            int a = count_points(mackerels, x1, y1, x2, y2);
            int b = count_points(sardines, x1, y1, x2, y2);
