                best_min_x = x1;
                best_max_x = x2;
                best_min_y = y1;
                best_max_y = y2;
            }
        }

        // 4. increase min_y to sy + 1
        x1 = min_x_m;
        x2 = max_x_m;
        y1 = sy + 1;
        y2 = max_y_m;
        if (x1 <= x2 && y1 <= y2) {
            int a = count_points(mackerels, x1, y1, x2, y2);
            int b = count_points(sardines, x1, y1, x2, y2);
