using namespace std;

struct Point {
    int x, y;
};

struct Rect {
    int lx, rx, by, ty;
};

int main() {
    int N;
    cin >> N;
    vector<Point> mackerels;
    vector<Point> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.emplace_back(x, y);
        } else {
            sardines.emplace_back(x, y);
        }
    }

    // Compute initial bounding box for mackerels
    int min_x = INT_MAX;
    int max_x = INT_MIN;
    int min_y = INT_MAX;
    int max_y = INT_MIN;
    for (const auto& p : mackerels) {
        if (p.x < min_x) min_x = p.x;
        if (p.x > max_x) max_x = p.x;
        if (p.y < min_y) min_y = p.y;
        if (p.y > max_y) max_y = p.y;
    }

    // Count sardines in initial rectangle
    int sardine_count_initial = 0;
    for (const auto& s : sardines) {
        if (s.x >= min_x && s.x <= max_x && s.y >= min_y && s.y <= max_y) {
            sardine_count_initial++;
        }
    }

    // If no sardines, output initial rectangle
    if (sardine_count_initial == 0) {
        cout << 4 << endl;
        cout << min_x << " " << min_y << endl;
        cout << max_x << " " << min_y << endl;
        cout << max_x << " " << max_y << endl;
        cout << min_x << " " << max_y << endl;
        return 0;
    }

    // Generate candidates
    vector<Rect> candidates;
    vector<Point> s_in_initial;

    // Collect sardines inside the initial rectangle
    for (const auto& s : sardines) {
        if (s.x >= min_x && s.x <= max_x && s.y >= min_y && s.y <= max_y) {
            s_in_initial.push_back(s);
        }
    }

    // Generate candidate rectangles
    for (const auto& s : s_in_initial) {
        int sx = s.x;
        int sy = s.y;

        // Case 1: move left to sx + 1
        int new_left = sx + 1;
        int new_right = max_x;
        if (new_left < new_right) {
            candidates.emplace_back(Rect{new_left, new_right, min_y, max_y});
        }

        // Case 2: move right to sx - 1
        int new_left2 = min_x;
        int new_right2 = sx - 1;
        if (new_left2 < new_right2) {
            candidates.emplace_back(Rect{new_left2, new_right2, min_y, max_y});
        }

        // Case 3: move bottom to sy + 1
        int new_bottom3 = sy + 1;
        int new_top3 = max_y;
        if (new_bottom3 < new_top3) {
            candidates.emplace_back(Rect{min_x, max_x, new_bottom3, new_top3});
        }

        // Case 4: move top to sy - 1
        int new_top4 = sy - 1;
        int new_bottom4 = min_y;
        if (new_bottom4 < new_top4) {
            candidates.emplace_back(Rect{min_x, max_x, new_bottom4, new_top4});
        }
    }

    // Add the initial rectangle as a candidate
    candidates.emplace_back(Rect{min_x, max_x, min_y, max_y});

    // Evaluate all candidates to find the best one
    int best_a = -1;
    int best_b = 0;
    int best_rect_index = 0;

    for (size_t i = 0; i < candidates.size(); ++i) {
        const Rect& rect = candidates[i];
        int a = 0, b = 0;

        // Count mackerels in the current rectangle
        for (const auto& p : mackerels) {
            if (p.x >= rect.lx && p.x <= rect.rx && p.y >= rect.by && p.y <= rect.ty) {
                a++;
            }
        }

        // Count sardines in the current rectangle
        for (const auto& s : sardines) {
            if (s.x >= rect.lx && s.x <= rect.rx && s.y >= rect.by && s.y <= rect.ty) {
                b++;
            }
        }

        if (a - b > best_a - best_b) {
            best_a = a;
            best_b = b;
            best_rect_index = static_cast<int>(i);
        }
    }

    const Rect& best_rect = candidates[best_rect_index];
    cout << 4 << endl;
    cout << best_rect.lx << " " << best_rect.by << endl;
    cout << best_rect.rx << " " << best_rect.by << endl;
    cout << best_rect.rx << " " << best_rect.ty << endl;
    cout << best_rect.lx << " " << best_rect.ty << endl;

    return 0;
}

