#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
#include <cmath>

using namespace std;

struct Point {
    int x, y;
    int type; // 1 for mackerel, -1 for sardine
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int N;
    cin >> N;

    vector<Point> all_points;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        Point p = {x, y, i < N ? 1 : -1};
        all_points.push_back(p);
    }

    // Separate mackerels and sardines
    vector<Point> mackerels;
    vector<Point> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        if (all_points[i].type == 1) {
            mackerels.push_back(all_points[i]);
        } else {
            sardines.push_back(all_points[i]);
        }
    }

    // Compute MBB for mackerels
    int x_min = numeric_limits<int>::max();
    int x_max = numeric_limits<int>::min();
    int y_min = numeric_limits<int>::max();
    int y_max = numeric_limits<int>::min();

    for (const auto& p : mackerels) {
        x_min = min(x_min, p.x);
        x_max = max(x_max, p.x);
        y_min = min(y_min, p.y);
        y_max = max(y_max, p.y);
    }

    // Function to count number of points in rectangle
    auto count_points = [&](int x1, int y1, int x2, int y2, const vector<Point>& points) -> int {
        int cnt = 0;
        for (const auto& p : points) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                cnt++;
            }
        }
        return cnt;
    };

    // Check if MBB has any sardines
    vector<Point> sardines_in_mbb;
    for (const auto& s : sardines) {
        if (s.x >= x_min && s.x <= x_max && s.y >= y_min && s.y <= y_max) {
            sardines_in_mbb.push_back(s);
        }
    }

    // If no sardines in MBB, use it
    if (sardines_in_mbb.empty()) {
        int w = x_max - x_min;
        int h = y_max - y_min;
        if (2 * (w + h) <= 400000) {
            cout << 4 << endl;
            cout << x_min << " " << y_min << endl;
            cout << x_max << " " << y_min << endl;
            cout << x_max << " " << y_max << endl;
            cout << x_min << " " << y_max << endl;
            return 0;
        } else {
            cout << 4 << endl;
            cout << x_min << " " << y_min << endl;
            cout << x_max << " " << y_min << endl;
            cout << x_max << " " << y_max << endl;
            cout << x_min << " " << y_max << endl;
            return 0;
        }
    }

    // Else, generate candidates
    int best_a_minus_b = -1;
    int best_x1 = x_min, best_y1 = y_min, best_x2 = x_max, best_y2 = y_max;

    for (const auto& s : sardines_in_mbb) {
        // Generate candidates by adjusting x to exclude s
        int x1_adj = x_min;
        int x2_adj = s.x - 1;
        if (x1_adj <= x2_adj) {
            int w = x2_adj - x1_adj;
            int h = y_max - y_min;
            int perimeter = 2 * (w + h);
            if (perimeter <= 400000) {
                int a = count_points(x1_adj, y_min, x2_adj, y_max, mackerels);
                int b = count_points(x1_adj, y_min, x2_adj, y_max, sardines);
                int current = a - b;
                if (current > best_a_minus_b) {
                    best_a_minus_b = current;
                    best_x1 = x1_adj;
                    best_y1 = y_min;
                    best_x2 = x2_adj;
                    best_y2 = y_max;
                }
            }
        }
        x1_adj = s.x + 1;
        x2_adj = x_max;
        if (x1_adj <= x2_adj) {
            int w = x2_adj - x1_adj;
            int h = y_max - y_min;
            int perimeter = 2 * (w + h);
            if (perimeter <= 400000) {
                int a = count_points(x1_adj, y_min, x2_adj, y_max, mackerels);
                int b = count_points(x1_adj, y_min, x2_adj, y_max, sardines);
                int current = a - b;
                if (current > best_a_minus_b) {
                    best_a_minus_b = current;
                    best_x1 = x1_adj;
                    best_y1 = y_min;
                    best_x2 = x2_adj;
                    best_y2 = y_max;
                }
            }
        }

        // Adjust y to exclude s
        int y1_adj = y_min;
        int y2_adj = s.y - 1;
        if (y1_adj <= y2_adj) {
            int w = x_max - x_min;
            int h = y2_adj - y1_adj;
            int perimeter = 2 * (w + h);
            if (perimeter <= 400000) {
                int a = count_points(x_min, y1_adj, x_max, y2_adj, mackerels);
                int b = count_points(x_min, y1_adj, x_max, y2_adj, sardines);
                int current = a - b;
                if (current > best_a_minus_b) {
