struct Rect {
    int x1, x2, y1, y2;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<Point> mackerels;
    vector<Point> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    auto compute_ab = [&](int x1, int x2, int y1, int y2) {
        int a = 0, b = 0;
        for (const auto& p : mackerels) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                a++;
            }
        }
        for (const auto& p : sardines) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                b++;
            }
        }
        return make_pair(a, b);
    };

    // Find initial rectangle
    int min_x_m = INT_MAX, max_x_m = INT_MIN, min_y_m = INT_MAX, max_y_m = INT_MIN;
    for (const auto& p : mackerels) {
        min_x_m = min(min_x_m, p.x);
        max_x_m = max(max_x_m, p.x);
        min_y_m = min(min_y_m, p.y);
        max_y_m = max(max_y_m, p.y);
    }
    Rect initial_rect = {min_x_m, max_x_m, min_y_m, max_y_m};
    int a_initial, b_initial;
    tie(a_initial, b_initial) = compute_ab(initial_rect.x1, initial_rect.x2, initial_rect.y1, initial_rect.y2);
    double best_val = static_cast<double>(a_initial - b_initial);
    Rect best_rect = initial_rect;

    // Iterate over each sardine to find better candidate rectangles
    for (const auto& s : sardines) {
        // Case 1: x < s.x
        vector<Point> m_x_less;
        for (const auto& m : mackerels) {
            if (m.x < s.x) {
                m_x_less.push_back(m);
            }
        }
        if (!m_x_less.empty()) {
            int x1 = INT_MAX, x2 = INT_MIN;
            int y1 = INT_MAX, y2 = INT_MIN;
            for (const auto& m : m_x_less) {
                x1 = min(x1, m.x);
                x2 = max(x2, m.x);
                y1 = min(y1, m.y);
                y2 = max(y2, m.y);
            }
            if (x1 < x2 && y1 < y2) {
                int a, b;
                tie(a, b) = compute_ab(x1, x2, y1, y2);
                double current_val = static_cast<double>(a - b);
                if (current_val > best_val) {
                    best_val = current_val;
                    best_rect = {x1, x2, y1, y2};
                }
            }
        }

        // Case 2: x > s.x
        vector<Point> m_x_more;
        for (const auto& m : mackerels) {
            if (m.x > s.x) {
                m_x_more.push_back(m);
            }
