                    best_val = current_val;
                    best_rect = {x1, x2, y1, y2};
                }
            }
        }
    }

    // Iterative refinement: try to exclude sardines that are inside current best_rect
    const int MAX_ITERATIONS = 10;
    for (int iter = 0; iter < MAX_ITERATIONS; ++iter) {
        vector<Point> sardines_in_rect;
        for (const auto& s : sardines) {
            if (s.x >= best_rect.x1 && s.x <= best_rect.x2 && s.y >= best_rect.y1 && s.y <= best_rect.y2) {
