    int min_m_x = INT_MAX, max_m_x = INT_MIN, min_m_y = INT_MAX, max_m_y = INT_MIN;
    for (const auto &p : mackerels) {
        min_m_x = min(min_m_x, p.x);
        max_m_x = max(max_m_x, p.x);
        min_m_y = min(min_m_y, p.y);
        max_m_y = max(max_m_y, p.y);
    }

    auto compute_ab = [&](int x1, int x2, int y1, int y2) {
        int a = 0, b = 0;
        for (const auto &p : mackerels) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                a++;
            }
        }
        for (const auto &p : sardines) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                b++;
            }
        }
        return make_pair(a, b);
    };

    // Initial rectangle
    int best_a = 0, best_b = 0;
    int best_x1 = min_m_x, best_x2 = max_m_x, best_y1 = min_m_y, best_y2 = max_m_y;
    tie(best_a, best_b) = compute_ab(best_x1, best_x2, best_y1, best_y2);
    double best_val = static_cast<double>(best_a - best_b);

    for (const auto &s : sardines) {
