        if (x1 < x2 && y1 < y2) {
            int a, b;
            tie(a, b) = compute_ab(x1, x2, y1, y2);
            double current_val = static_cast<double>(a - b);
            if (current_val > best_val) {
                best_val = current_val;
                best_x1 = x1;
                best_x2 = x2;
                best_y1 = y1;
                best_y2 = y2;
            }
        }

        // Case 2: x_right
        x1 = sx + 1;
        x2 = max_m_x;
        if (x1 < x2 && y1 < y2) {
            int a, b;
            tie(a, b) = compute_ab(x1, x2, y1, y2);
            double current_val = static_cast<double>(a - b);
            if (current_val > best_val) {
