        y1 = min_m_y;
        y2 = sy - 1;
        if (y1 < y2 && best_x1 < best_x2) {
            int a, b;
            tie(a, b) = compute_ab(best_x1, best_x2, y1, y2);
            double current_val = static_cast<double>(a - b);
            if (current_val > best_val) {
                best_val = current_val;
                best_y1 = y1;
                best_y2 = y2;
            }
        }

        // Case 4: y_right
        y1 = sy + 1;
        y2 = max_m_y;
        if (y1 < y2 && best_x1 < best_x2) {
