                if (new_left2 < new_right2 && new_bottom2 < new_top2) {
                    int count_m = 0;
                    int count_s = 0;
                    for (auto pm : mackerels) {
                        if (pm.x >= new_left2 && pm.x <= new_right2 && pm.y >= new_bottom2 && pm.y <= new_top2) {
                            count_m++;
                        }
                    }
                    for (auto ps : sardines) {
                        if (ps.x >= new_left2 && ps.x <= new_right2 && ps.y >= new_bottom2 && ps.y <= new_top2) {
                            count_s++;
                        }
                    }
                    int score = count_m - count_s;
                    if (score > best_score) {
                        best_score = score;
                        best_left = new_left2;
                        best_right = new_right2;
                        best_bottom = new_bottom2;
                        best_top = new_top2;
                    }
                }

                // Try to move bottom boundary to the top of this sardine's y
                int new_left3 = left_m;
                int new_right3 = right_m;
                int new_bottom3 = max(bottom_m, p.y + 1);
                int new_top3 = top_m;
                if (new_left3 < new_right3 && new_bottom3 < new_top3) {
                    int count_m = 0;
                    int count_s = 0;
                    for (auto pm : mackerels) {
                        if (pm.x >= new_left3 && pm.x <= new_right3 && pm.y >= new_bottom3 && pm.y <= new_top3) {
                            count_m++;
                        }
                    }
                    for (auto ps : sardines) {
                        if (ps.x >= new_left3 && ps.x <= new_right3 && ps.y >= new_bottom3 && ps.y <= new_top3) {
                            count_s++;
                        }
                    }
                    int score = count_m - count_s;
                    if (score > best_score) {
                        best_score = score;
                        best_left = new_left3;
                        best_right = new_right3;
                        best_bottom = new_bottom3;
                        best_top = new_top3;
                    }
                }

                // Try to move top boundary to the bottom of this sardine's y
                int new_left4 = left_m;
                int new_right4 = right_m;
                int new_bottom4 = bottom_m;
                int new_top4 = min(top_m, p.y - 1);
                if (new_left4 < new_right4 && new_bottom4 < new_top4) {
                    int count_m = 0;
                    int count_s = 0;
                    for (auto pm : mackerels) {
                        if (pm.x >= new_left4 && pm.x <= new_right4 && pm.y >= new_bottom4 && pm.y <= new_top4) {
                            count_m++;
                        }
                    }
                    for (auto ps : sardines) {
                        if (ps.x >= new_left4 && ps.x <= new_right4 && ps.y >= new_bottom4 && ps.y <= new_top4) {
                            count_s++;
                        }
                    }
                    int score = count_m - count_s;
                    if (score > best_score) {
                        best_score = score;
                        best_left = new_left4;
                        best_right = new_right4;
                        best_bottom = new_bottom4;
                        best_top = new_top4;
                    }
                }
            }
        }
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_left << ' ' << best_bottom << endl;
    cout << best_right << ' ' << best_bottom << endl;
    cout << best_right << ' ' << best_top << endl;
    cout << best_left << ' ' << best_top << endl;

    return 0;
}
